const defaultState=()=>({page:'overview',role:'buyer',sku:'P001',warehouse:'WH001',month:10,year:2026,forecastSearch:'',riskScenario:'shortage',orderSelected:'PO-2026-001',orderFilter:'all',notifyRead:false,forecastOverrides:{},settingsMin:{},settingsMax:{},supplierCycles:{},orders:[{id:'PO-2026-001',supplier:'S01',status:'draft',date:'14.10.2026',eta:'18.11.2026',version:1,owner:'А. Каримов',items:[{sku:'P001',recommended:120,qty:120},{sku:'P002',recommended:300,qty:340},{sku:'P004',recommended:300,qty:300}],changes:[{sku:'P002',from:300,to:340,reason:'Дополнительный спрос региональных складов'}]},{id:'PO-2026-002',supplier:'S02',status:'review',date:'13.10.2026',eta:'28.10.2026',version:2,owner:'А. Каримов',items:[{sku:'P001',recommended:150,qty:150},{sku:'P003',recommended:100,qty:110},{sku:'P006',recommended:200,qty:200}],changes:[{sku:'P003',from:100,to:110,reason:'Уточнение спроса аптечных сетей'}]},{id:'PO-2026-003',supplier:'S03',status:'approved',date:'11.10.2026',eta:'15.11.2026',version:1,owner:'М. Ахмедова',items:[{sku:'P002',recommended:400,qty:400},{sku:'P005',recommended:200,qty:200}],changes:[]},{id:'PO-2026-004',supplier:'S05',status:'draft',date:'14.10.2026',eta:'26.10.2026',version:1,owner:'А. Каримов',items:[{sku:'P001',recommended:80,qty:80},{sku:'P004',recommended:120,qty:120}],changes:[]}],allocations:{WH001:220,WH003:180,WH002:100,WH004:0,WH005:0},allocationApproved:false,transferStatuses:{},shipmentDelta:7,scenarioActions:[],events:[{type:'alert',text:'Риск дефицита: P002 / WH003',details:'Изменение ETA поставки PO-0002',time:'Сегодня, 09:12'},{type:'info',text:'Расчёт прогноза Production завершён',details:'Версия 2.4 · 15 SKU · 70 складов',time:'Сегодня, 08:45'},{type:'amber',text:'Заявка PO-2026-002 ожидает согласования',details:'Ответственный: директор по закупкам',time:'Вчера, 17:30'},{type:'success',text:'Партия на РЦ принята',details:'Поступление 500 шт. · P002 Амоксициллин',time:'Вчера, 15:20'}]});
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch(e){}}
const product=id=>db.products.find(x=>x.id===id)||{id,name:id,minDays:20,maxDays:45,storage:'Обычное'};
const warehouse=id=>db.warehouses.find(x=>x.id===id)||{id,city:id,name:id};
const supplier=id=>db.suppliers.find(x=>x.id===id)||{id,name:id,cycle:30};
const offer=(sku,sup)=>db.offers.find(x=>x.sku===sku&&x.supplier===sup)||db.offers.find(x=>x.sku===sku)||{price:10000,moq:20,step:10,lead:30};
const stock=(sku,wh)=>db.inventory.find(x=>x.sku===sku&&x.warehouse===wh)||{available:0,onHand:0,reserved:0};
const forecastEntry=(sku,wh)=>db.forecasts.find(x=>x.sku===sku&&x.warehouse===wh)||{base:.5,trend:1,season:Array(12).fill(1),sold12:0,days12:0,series:Array(12).fill(0)};
function factors(sku,wh,month=state.month){
 const e=forecastEntry(sku,wh); const p=product(sku), key=sku+'|'+wh+'|'+month;
 const base={season:e.season[(month-1)%12]||1,trend:e.trend||1,holiday:['Антибиотики','Витамины'].includes(p.category)?1.04:1.02,weather:p.category==='Антигистаминные'?1.06:p.category==='Антибиотики'?1.025:1,promo:['P001','P003','P007'].includes(sku)?1.08:1};
 return {...base,...(state.forecastOverrides[key]||{})};
}
function forecastCalc(sku,wh,month=state.month,year=state.year){
 const r=forecastEntry(sku,wh),f=factors(sku,wh,month),days=daysInMonth(year,month);
 const qty=Math.round(r.base*days*f.season*f.trend*f.holiday*f.weather*f.promo);
 return {qty:Math.max(0,qty),base:r.base,days,...f,entry:r,baseline:Math.round(r.base*days*f.season*f.trend)};
}
const statusLabel={draft:'Черновик',review:'На согласовании',approved:'Утверждена',exported:'Экспортирована',sent:'Отправлена',returned:'На доработке'};
const statusColor={draft:'grey',review:'amber',approved:'green',exported:'blue',sent:'blue',returned:'red'};
const status=(label,color='grey',dot=true)=>`<span class="status ${color}">${dot?'<span class="status-dot"></span>':''}${esc(label)}</span>`;
const order=()=>state.orders.find(x=>x.id===state.orderSelected)||state.orders[0];
const orderTotal=o=>o.items.reduce((sum,r)=>sum+(r.qty||0)*(offer(r.sku,o.supplier).price||0),0);
function event(type,text,details){state.events.unshift({type,text,details,time:'Только что'});state.notifyRead=false;state.events=state.events.slice(0,55);persist()}
function showToast(text,type='success'){toastList=[{text,type}];renderToasts();clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>{toastList=[];renderToasts()},4600)}
function renderToasts(){const node=$('#toasts');if(node)node.innerHTML=toastList.map(t=>`<div class="toast ${t.type}">${ic(t.type==='error'?'alert':'check',17)}<span>${esc(t.text)}</span></div>`).join('')}
function navigate(pg){if(!titles[pg])pg='overview';state.page=pg;state.forecastSearch='';drawer=null;modal=null;persist();history.replaceState(null,'','#/'+pg);render();window.scrollTo(0,0)}
const header=(title,desc='',actions='')=>`<div class="page-header"><div><div class="eyebrow">Smartup / SCM / ${esc(title)}</div><h1 class="page-title">${esc(title)}</h1><div class="page-sub">${desc}</div></div><div class="page-head-actions">${actions}</div></div>`;
const button=(txt,act,klass='btn',extra='')=>`<button type="button" class="${klass}" data-action="${act}" ${extra}>${txt}</button>`;
const iconButton=(name,act,label='')=>`<button class="icon-btn" title="${esc(label)}" aria-label="${esc(label)}" data-action="${act}">${ic(name,18)}</button>`;
function render(){
 const page=state.page; const visibleNav=state.role==='warehouse'?nav.filter(n=>['allocation','journal'].includes(n[0])):state.role==='director'?nav.filter(n=>['overview','risks','approvals','journal'].includes(n[0])):nav; const roleNames={buyer:'Снабженец',director:'Директор',warehouse:'Заведующий складом',admin:'Администратор'};
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-name">Smartup<span>.</span></div><div class="brand-sub">SCM / УПРАВЛЕНИЕ ЦЕПОЧКАМИ</div></div><div class="side-cap">Рабочее пространство</div><nav class="nav">${visibleNav.map(([id,txt,icon])=>`<button class="nav-button ${page===id?'active':''}" data-nav="${id}" title="${txt}" aria-current="${page===id?'page':'false'}">${ic(icon)}<span>${txt}</span>${id==='approvals'&&state.orders.some(o=>o.status==='review')?`<b class="nav-count">${state.orders.filter(o=>o.status==='review').length}</b>`:''}</button>`).join('')}</nav><div class="side-spacer"></div><div class="side-footer"><div><span class="connection"></span> Система готова</div><small>Smartup SCM · Demo v2.4</small><small>Данные на 01.10.2026</small></div></aside><div class="main"><header class="topbar"><div class="breadcrumbs"><strong>Smartup</strong><span class="slash">/</span><span>SCM</span><span class="slash">/</span><strong>${esc(titles[page])}</strong></div><div class="top-actions"><span class="demo-flag">INTERACTIVE DEMO</span><div class="top-divider"></div><span class="note">${ic('clock',13)} Обновлено ${today}</span><button class="icon-btn" data-nav="journal" title="Уведомления">${ic('bell',18)}${!state.notifyRead?'<i class="notification-dot"></i>':''}</button><select class="role-select" data-change="role" title="Переключить роль">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${state.role===k?'selected':''}>${v}</option>`).join('')}</select><div class="avatar">${state.role==='director'?'ДР':state.role==='warehouse'?'СК':state.role==='admin'?'АД':'СН'}</div></div></header><main class="content">${renderPage()}</main></div></div><div id="overlay">${renderOverlay()}</div><div id="toasts" class="toast-wrap" aria-live="polite"></div>`;
 renderToasts();
}
function renderPage(){switch(state.page){case'overview':return overviewPage();case'forecast':return forecastPage();case'purchases':return purchasesPage();case'allocation':return allocationPage();case'risks':return risksPage();case'approvals':return approvalsPage();case'journal':return journalPage();case'settings':return settingsPage();default:return overviewPage()}}
function lineChart(seriesA=[18,16,20,15,22,17,19,14,18,13,15,11],seriesB=[11,10,9,11,9,8,7,9,8,7,6,5],labels=['Ноя','Дек','Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт'],colors=['#cf6f75','#62b79e']){
 const width=660,height=206,pad={t:19,b:31,l:28,r:19};const all=[...seriesA,...seriesB];const upper=Math.max(10,Math.ceil(Math.max(...all)*1.2/5)*5);const low=0;
 const path=(a)=>a.map((v,i)=>`${i?'L':'M'}${pad.l+i*(width-pad.l-pad.r)/(a.length-1)} ${height-pad.b-(v-low)/(upper-low)*(height-pad.t-pad.b)}`).join(' ');
 return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Динамика рисков"><g stroke="#ebf0f5" stroke-width="1">${[0,1,2,3,4].map(i=>`<line x1="${pad.l}" x2="${width-pad.r}" y1="${pad.t+i*(height-pad.t-pad.b)/4}" y2="${pad.t+i*(height-pad.t-pad.b)/4}"/>`).join('')}</g><g fill="#9aaabd" font-size="10">${[0,1,2,3,4].map(i=>`<text text-anchor="end" x="${pad.l-9}" y="${pad.t+i*(height-pad.t-pad.b)/4+3}">${Math.round(upper*(4-i)/4)}</text>`).join('')}${labels.map((s,i)=>`<text text-anchor="middle" x="${pad.l+i*(width-pad.l-pad.r)/(labels.length-1)}" y="${height-8}">${esc(s)}</text>`).join('')}</g><path d="${path(seriesA)}" stroke="${colors[0]}" stroke-width="2.4" fill="none" stroke-linejoin="round" stroke-linecap="round"/><path d="${path(seriesB)}" stroke="${colors[1]}" stroke-width="2.4" fill="none" stroke-linejoin="round" stroke-linecap="round"/>${[seriesA,seriesB].map((s,j)=>s.map((n,i)=>`<circle cx="${pad.l+i*(width-pad.l-pad.r)/(s.length-1)}" cy="${height-pad.b-n/upper*(height-pad.t-pad.b)}" r="2.8" fill="${colors[j]}" stroke="#fff" stroke-width="1.2"/>`).join('')).join('')}</svg>`;
}
const badgeSet=(s)=>status(statusLabel[s]||s,statusColor[s]||'grey');
function overviewPage(){
 const pending=state.orders.filter(o=>o.status==='review').length;
 const metrics=[['SKU под риском OOS','8', '12 складов · требуют действий','red','alert','risks'],['Запас выше Max','14','9 складов · потенциальный избыток','amber','box','risks'],['На согласовании',pending,'заявок ожидают директора','', 'shield','approvals'],['Задержанные поставки','2','1 критическая · 1 информационная','red','truck','risks']];
 return header('Центр управления запасами','Контролируйте отклонения, проверяйте решения и запускайте действия — без ручных таблиц Excel.',`${button(ic('refresh')+' Пересчитать прогноз','recalculate','btn btn-primary')}`)+`<div class="kpi-grid">${metrics.map(m=>`<button class="metric" data-nav="${m[5]}"><div class="metric-top"><span>${m[0]}</span><span class="metric-icon ${m[3]}">${ic(m[4])}</span></div><div class="metric-number">${m[1]}</div><div class="metric-meta">${m[2]}</div></button>`).join('')}</div><div class="chart-grid"><div class="panel"><div class="panel-head"><div><div class="panel-title">Динамика рисков OOS / OS</div><div class="panel-desc">Помесячно · доля проблемных позиций, %</div></div><div class="legend"><span><i class="legend-line" style="background:#cf6f75"></i>Дефицит OOS</span><span><i class="legend-line" style="background:#62b79e"></i>Избыток OS</span></div></div><div class="chart">${lineChart()}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Требуют решения</div><div class="panel-desc">Ранжировано по срочности и бизнес-риску</div></div>${button('Все риски '+ic('chevron',13),'go-risks','btn btn-sm')}</div><div class="priority-list"><div class="priority-item"><div class="prio-left"><span class="priority-dot"></span><div><div class="prio-name">P002 · Амоксициллин</div><div class="prio-sub">WH003 · Наманган · OOS через 3 дня</div></div></div>${button('Открыть','risk-shortage','btn btn-sm')}</div><div class="priority-item"><div class="prio-left"><span class="priority-dot"></span><div><div class="prio-name">PO-0002 · GlobalMed</div><div class="prio-sub">Задержка поставки · +7 дней</div></div></div>${button('Открыть','risk-shortage','btn btn-sm')}</div><div class="priority-item"><div class="prio-left"><span class="priority-dot amber"></span><div><div class="prio-name">WH005 · Запас выше Max</div><div class="prio-sub">P001 · избыток 220 шт.</div></div></div>${button('Открыть','risk-overstock','btn btn-sm')}</div><div class="priority-item"><div class="prio-left"><span class="priority-dot amber"></span><div><div class="prio-name">Закупка PO-2026-002</div><div class="prio-sub">Согласование директора</div></div></div>${button('Открыть','go-approvals','btn btn-sm')}</div></div></div></div><div class="two-col"><div class="panel"><div class="panel-head"><div><div class="panel-title">Последние закупки</div><div class="panel-desc">Проекты заказов и их текущие статусы</div></div>${button('Все закупки '+ic('arrow',13),'go-purchases','btn btn-sm')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Заявка / поставщик</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>${state.orders.slice(0,4).map(o=>`<tr class="click-row" data-open-order="${o.id}"><td><strong>${o.id}</strong><div class="note">${supplier(o.supplier).name}</div></td><td class="mono">${money(orderTotal(o))}</td><td>${badgeSet(o.status)}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Операционная сводка</div><div class="panel-desc">Контур закупок и распределения</div></div></div><div class="panel-pad"><div class="kv-row"><span>SKU в справочнике демо</span><strong>${db.products.length}</strong></div><div class="kv-row"><span>Региональных складов</span><strong>${db.warehouses.length-1}</strong></div><div class="kv-row"><span>Товарных остатков (SKU × склад)</span><strong>${fmt(db.inventory.length)}</strong></div><div class="kv-row"><span>Поставщиков</span><strong>${db.suppliers.length}</strong></div><div class="kv-row"><span>Версия прогнозной модели</span><strong>Production Demo v2.4</strong></div><hr class="divider"/><div class="insight">${ic('info',14)} <strong>Рабочий процесс:</strong> прогноз → рекомендация → согласование → экспорт → приёмка → распределение.</div></div></div></div><div class="footnote">${ic('info',13)} Данные справочников и срез остатков взяты из файлов тестового задания; показатели риска, заказы и действия — демонстрационные сценарии.</div>`;
}
function forecastPage(){
 const products=db.products.filter(p=>!state.forecastSearch||[p.id,p.name,p.category].some(v=>String(v).toLowerCase().includes(state.forecastSearch.toLowerCase())));
 const rows=products.map(p=>({p,f:forecastCalc(p.id,state.warehouse),s:stock(p.id,state.warehouse)}));
 const totals=rows.reduce((v,r)=>v+r.f.qty,0);
 return header('Прогноз спроса','Production Forecast · SKU × склад × период. Прозрачная модель с объяснением каждого коэффициента.',`${button(ic('history')+' История расчётов','go-journal','btn')}${button(ic('refresh')+' Пересчитать','recalculate','btn btn-primary')}`)+`<div class="filters"><span class="filter-label">${ic('calendar',14)} Период</span><select class="select" data-change="month">${[10,11,12].map((m,i)=>`<option value="${m}" ${m===state.month?'selected':''}>${['Октябрь','Ноябрь','Декабрь'][i]} 2026</option>`).join('')}</select><span class="filter-label">${ic('box',14)} Склад</span><select class="select" data-change="warehouse">${db.warehouses.filter(w=>w.id!=='WH000').map(w=>`<option value="${w.id}" ${w.id===state.warehouse?'selected':''}>${w.id} · ${esc(w.city)}</option>`).join('')}</select><input class="input search" type="search" placeholder="Поиск SKU или категории" data-change="forecastSearch" value="${esc(state.forecastSearch)}"/>${status('Модель Production Demo v2.4','blue')}</div><div class="subgrid mb-16"><div class="small-metric"><div class="s-label">Прогноз по выбранному складу</div><div class="s-num">${fmt(totals)} шт.</div><div class="s-sub">${products.length} SKU · ${state.month}.2026</div></div><div class="small-metric"><div class="s-label">Факторов в модели</div><div class="s-num">5 коэффициентов</div><div class="s-sub">Сезонность · тренд · праздники · погода · промо</div></div><div class="small-metric"><div class="s-label">Данные</div><div class="s-num">84 месяца</div><div class="s-sub">Историческая выборка 2019–2026</div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Прогноз по товарам</div><div class="panel-desc">Нажмите на строку, чтобы увидеть формулу и настроить коэффициенты</div></div><span class="demo-flag">РАСШИРЕННЫЙ ПРОГНОЗ</span></div><div class="table-wrap"><table class="table"><thead><tr><th>SKU / наименование</th><th>Категория</th><th class="right">Продано, 12 мес.</th><th class="right">Дни наличия</th><th class="right">База / день</th><th class="right">K сезон.</th><th class="right">K тренда</th><th class="right">Прогноз</th><th>Действие</th></tr></thead><tbody>${rows.map(({p,f})=>`<tr class="click-row" data-open-forecast="${p.id}"><td><strong>${p.id} · ${esc(p.name)}</strong><div class="note">${esc(p.dose)} · ${esc(p.pack)}</div></td><td>${esc(p.category)}</td><td class="right mono">${fmt(f.entry.sold12)}</td><td class="right mono">${fmt(f.entry.days12)}</td><td class="right mono">${dec(f.base)}</td><td class="right mono">${dec(f.season)}</td><td class="right mono">${dec(f.trend)}</td><td class="right mono"><strong>${fmt(f.qty)} шт.</strong></td><td><button class="link" data-open-forecast="${p.id}">Почему? ${ic('chevron',13)}</button></td></tr>`).join('')}</tbody></table></div></div><div class="footnote">${ic('info',13)} Исторические база, сезонность и тренд вычислены из проектной истории. Коэффициенты праздников, погоды и промо — сценарные оценки для визуализации Production-модели.</div>`;
}
function recommendPurchase(sku,sid){
 const p=product(sku),sup=supplier(sid),of=offer(sku,sid),regional=db.warehouses.filter(x=>x.id!=='WH000');
 const daily=regional.reduce((sum,w)=>sum+forecastCalc(sku,w.id).qty/31,0);
 const lead=(sup.processing||7)+(sup.delivery||21)+(sup.customs||7);
 const horizon=lead+(state.supplierCycles[sid]||sup.cycle||30);
 const safety=daily*(state.settingsMin[sku]??p.minDays);
 const avail=stock(sku,'WH000').available||0;
 const ontime=db.shipments.filter(sh=>sh.sku===sku&&sh.supplier===sup.name&&sh.eta<='2026-11-20').reduce((n,s)=>n+s.qty,0);
 const net=Math.max(0,Math.ceil(daily*horizon+safety-avail-ontime));
 const step=of.step||10; const moq=of.moq||10;
 return {qty:net?Math.ceil(Math.max(net,moq)/step)*step:0,daily,lead,horizon,safety,avail,ontime,net,of};
}
