  const was=row.qty;row.qty=qty;o.version++;o.changes.push({sku:row.sku,from:was,to:qty,reason});event('amber','Изменена закупка '+o.id,`${modal.sku}: ${was} → ${qty} шт. · ${reason}`);modal=null;persist();render();return showToast('Количество обновлено. Сумма заявки пересчитана.');
